#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe http-follow-links-inside-the-served-folder. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site/docs plain/docs outside
printf '%s\n' 'the guide, inside the served folder' > site/docs/guide.txt
printf '%s\n' 'the guide, inside the served folder' > plain/docs/guide.txt
printf '%s\n' 'outside the served folder' > outside/secret.txt
cat > make-links.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Makes the same four symbolic links in site and in plain. MSYS asks Git Bash on Windows
# for real links; other systems ignore it.
export MSYS=winsymlinks:nativestrict
for root in site plain; do
  ln -s docs/guide.txt "$root/latest.txt"          # a file link that stays inside
  ln -s docs "$root/current"                        # a folder link that stays inside
  ln -s ../outside/secret.txt "$root/leak.txt"      # a link that leaves the folder
  ln -s leak.txt "$root/hop.txt"                    # a link inside to a link that leaves
done
EOF
sh make-links.sh
surl -v --log-file links.log --follow-symlinks --directory site http://127.0.0.1:8080/ &
sleep 1
curl -s -w "%{http_code}\n" http://127.0.0.1:8080/latest.txt
kill $(jobs -p)
